import{_ as n,C as r,o as s,c as a,j as e,a as i,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/run-on-this-computer.png",k=JSON.parse(`{"title":"Run on this computer","description":"The run button in the desktop app's window: a run's, an execution's, a cluster's or a test's Playwright tests run in the project's linked folder in one click, or from the run dialog with their options, beside the project's CI actions.","frontmatter":{"title":"Run on this computer","description":"The run button in the desktop app's window: a run's, an execution's, a cluster's or a test's Playwright tests run in the project's linked folder in one click, or from the run dialog with their options, beside the project's CI actions.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-on-this-computer.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-on-this-computer.html"}],["meta",{"property":"og:title","content":"Run on this computer | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The run button in the desktop app's window: a run's, an execution's, a cluster's or a test's Playwright tests run in the project's linked folder in one click, or from the run dialog with their options, beside the project's CI actions."}]]},"headers":[],"relativePath":"features/run-on-this-computer.md","filePath":"features/run-on-this-computer.md","lastUpdated":1795729315000}`),u={name:"features/run-on-this-computer.md"};function c(p,t,g,f,m,w){const o=r("Needs");return s(),a("div",null,[t[0]||(t[0]=e("h1",{id:"run-on-this-computer",tabindex:"-1"},[i("Run on this computer "),e("a",{class:"header-anchor",href:"#run-on-this-computer","aria-label":'Permalink to "Run on this computer"'},"​")],-1)),h(o,{desktop:""}),t[1]||(t[1]=l('<p>In the <a href="./desktop.html">desktop app</a>&#39;s window, the <a href="./ci-rerun.html#the-run-dialog">run button</a> of a run, an execution, a failure cluster and a test runs the page&#39;s tests in the project&#39;s linked folder, with the folder&#39;s own Playwright and the app&#39;s bundled Node. Its dialog&#39;s <strong>Where</strong> lists <strong>This computer</strong> in place of your apps (<a href="./run-on-my-machine.html">Run on my machine</a>, which a browser offers), before the project&#39;s <a href="./ci-actions.html">CI actions</a>. The run streams into the <a href="./local-runs-tray.html">Local runs tray</a>, keeps going while you browse, and, with the Piwi reporter set up, reports to the app.</p><figure><img src="'+d+'" alt="The run dialog of a failed run in the desktop app: the failed tests, the flaky ones or every test under What; This computer picked under Where, in the linked folder, above a CI action; then the linked folder, the run options and the environment"><figcaption>A failed run&#39;s dialog in the desktop app, on This computer.</figcaption></figure><h2 id="one-click" tabindex="-1">One click <a class="header-anchor" href="#one-click" aria-label="Permalink to &quot;One click&quot;">​</a></h2><p>The button says what it runs, and runs it here in one click:</p><table tabindex="0"><thead><tr><th>Page</th><th>The button</th><th>Its other tests here</th></tr></thead><tbody><tr><td>Run</td><td><strong>Re-run 3 failed tests</strong>, else the flaky ones, else every test</td><td>The flaky tests and every test, by their files past 200 tests</td></tr><tr><td>Execution</td><td><strong>Re-run this test</strong></td><td>None: every test of its cluster runs on CI</td></tr><tr><td>Test</td><td><strong>Run this test</strong>, by its title, 20 times with a trace until it fails</td><td>None: Flake Lab runs from the <strong>Flakiness</strong> tab</td></tr><tr><td>Failure cluster, and its Verify section</td><td><strong>Re-run the 2 affected tests</strong>, as the verify command selects them</td><td>None</td></tr><tr><td>A run&#39;s <strong>Tests</strong> tab, tests selected</td><td><strong>Re-run 3 selected tests</strong>, on this computer alone</td><td>None</td></tr></tbody></table><p>It names what differs from Playwright&#39;s defaults, and the <a href="./environments.html">environment</a> of the run its tests come from (<strong>· headed · ×5 · Staging</strong>): the run is for that environment, with its <a href="./run-variables.html">run variables</a>. For a protected environment, the button&#39;s run is for none, and the dialog picks it.</p><p>While a run of those tests goes on, the button shows how far it is (<strong>Running 2/3…</strong>), then <strong>Passed</strong> or <strong>Failed</strong> for a few seconds; a click then opens the tray, and never stops anything.</p><p>After a send to a CI action, the button reads <strong>Run on this computer or CI</strong> and opens the dialog on that action, until a run here makes This computer its <strong>Where</strong> again. The button remembers the last one per project.</p><h2 id="the-arrow" tabindex="-1">The arrow <a class="header-anchor" href="#the-arrow" aria-label="Permalink to &quot;The arrow&quot;">​</a></h2><ul><li><strong>Runs this command</strong>: what the button runs, and the tests it leaves out, those with no file path Playwright takes, or no title when it selects them by title.</li><li><strong>Run once</strong> headless, headed, in the inspector or in UI mode, and <strong>Run other tests</strong>: the page&#39;s other tests.</li><li>The one-click runs on CI, as in a browser.</li><li><strong>Options of this button</strong>: <strong>Record trace</strong>, <a href="./watch-a-run.html#hold-failures"><strong>Hold failures</strong></a>, <strong>Repeat each</strong> with no retries, <strong>Stop at the first failing repetition</strong>, and <strong>Select tests by</strong> <code>file:line</code>, title or file. They apply to this button&#39;s runs until you leave the page; the project&#39;s defaults, which every button starts from, are in <strong>Project → Settings → Local folder</strong>.</li><li><strong>Run with options…</strong>, <strong>Copy as command</strong> (the command for your terminal, with the run variables), <strong>Project defaults…</strong>, <strong>Local runs</strong>, and the linked folder with <strong>Change linked folder…</strong>.</li></ul><h2 id="the-dialog" tabindex="-1">The dialog <a class="header-anchor" href="#the-dialog" aria-label="Permalink to &quot;The dialog&quot;">​</a></h2><p><strong>Run with options…</strong> opens the run dialog on This computer: <strong>What</strong>, <strong>Where</strong>, the linked folder with <strong>Change</strong>, the run options with <strong>Repeat each</strong> up to 1,000, the environment, and the exact commands. The options start from the button&#39;s and apply to that run alone. The environment starts on the last one picked for the folder; a protected one asks you to confirm each run, which keeps to the tests carrying its required tags. <strong>Run</strong> starts the run and closes the dialog.</p><h2 id="when-the-folder-is-not-ready" tabindex="-1">When the folder is not ready <a class="header-anchor" href="#when-the-folder-is-not-ready" aria-label="Permalink to &quot;When the folder is not ready&quot;">​</a></h2><p>With no folder linked, none of the tests in it, or no Playwright installed, the button opens the dialog, which says what to fix: <strong>Choose folder…</strong>, <strong>Choose the right folder…</strong> or <strong>Re-check after installing</strong>. A folder without the tests still runs, since a config may put them elsewhere. The arrow lists the same fixes. With no test it can select, the button opens the arrow, which says why.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>The desktop app only.</strong> A browser has no This computer: its run button asks your own apps instead.</li><li><strong>A run&#39;s tests, one test, a cluster&#39;s tests or a selection.</strong> A project&#39;s whole suite, its tagged tests and a Flake Lab experiment run on CI from the run button; Flake Lab also runs here from a test&#39;s <strong>Flakiness</strong> tab.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./desktop.html">Desktop app</a>: linking a project to its folder, reproduce and bisect.</li><li><a href="./local-runs-tray.html">Local runs tray</a>: each run, its <strong>Stop</strong> and its output.</li><li><a href="./desktop-runs.html">Desktop app runs</a>: each worker, paused, stepped and watched live.</li><li><a href="./ci-rerun.html">Re-run in CI</a>: the run button and dialog on CI.</li></ul>',18))])}const y=n(u,[["render",c]]);export{k as __pageData,y as default};
